  XW += x[109] * 1.1322399999999999e+02; // BC8H17
  XW += x[110] * 1.1322399999999999e+02; // CC8H17
  XW += x[111] * 1.1322399999999999e+02; // DC8H17
  XW += x[112] * 1.1221599999999999e+02; // IC8H16
  XW += x[113] * 1.1221599999999999e+02; // JC8H16
  XW += x[114] * 1.4522199999999998e+02; // AC8H17O2
